r"""
Trained (not exact) SU(3) sampler for the group commutator equation.

Given Z in SU(3), draws (X, Y) in SU(3) x SU(3) satisfying Z = X Y X^dagger
Y^dagger from a *trained* masked-autoregressive rational-quadratic-spline
flow -- unlike SU(2), no closed-form conditional sampler is known for SU(3)
(finding one is an open research question, not an engineering gap), so this
is the best available substitute, not an exact map.

Lazy `normflow` import
-----------------------
The trained model's architecture (`MatrixModule_`, the masked-autoregressive
context module, `SUnMatrixEulerParametrizer`) is defined in `normflow`, which
`lattice_ml` otherwise never depends on. `normflow` is therefore imported
only inside `_build_model`, the first time this sampler is actually called,
not at module import time -- importing this module (or all of `lattice_ml`)
never requires `normflow` to be installed; only calling
`sample_su3_group_commutator_xy_given_z` does. This is a stopgap: the
model's *inference* path (a masked-linear forward pass followed by an RQS
spline evaluation) does not fundamentally need `normflow`'s training
framework at all, only its own small numerical core (`normflow.lib.spline`)
-- porting just that piece natively into `lattice_ml` would remove this
dependency entirely, but hasn't been done yet.

Only the Q-conditional-flow, not the whole model
--------------------------------------------------
`su3_group_commutator.ipynb`'s full trained model is a `ChainRuleModule_`
over three layers -- `[D_module_ (None, already uniform), Q_module_
(conditional flow for Q given Z), Z_module_ (a trained flow that generates
Z itself from a flat seed)]` -- because that notebook also supports
generating Z from scratch. `xy_sampler`'s contract always takes Z as given,
so `Z_module_` is never needed here; this file reconstructs and loads
*only* `Q_module_` (`GroupCommutatorQTransform_`, the `layers.1.*` keys of
the exported state dict), not the full `ChainRuleModule_`/`ModuleList_`/
`RQSplineNet_`/`MultiChannelModule_` machinery the complete model uses for
`Z_module_`.

Weights, provenance, and correctness
-------------------------------------
The embedded weight blob is exported from
`normflow/examples/conditional_flows/sun_group_commutator/SU3/
su3_group_commutator.ipynb` (`model.network_fn_.get_weights_blob()`, its
own `load_pretrained_model` branch) -- the *self-learning* model, trained
by minimizing reverse KL against its own reweighted samples via path-
gradient estimators (`path_gradient_autodiff=True`) for 50,000 epochs,
reaching `Final loss = 0.0028`. It is a masked-autoregressive 8-segment
RQS flow with 3 hidden layers of width 32 (5764 parameters in `Q_module_`
alone), conditioned on `spec(Z)`, and uses `iaf=True` (see
`MaskedAutoRegContextModule_`).

Verified against that notebook's own model, loading only `Q_module_`'s
weights (`layers.1.*`, stripped of that prefix; `load_state_dict` reports
zero missing/unexpected keys): `Z = X Y X^dagger Y^dagger` holds to
~1e-12 over 262,144 fresh samples. Fixed-Z self-ESS (same
`compute_ess(logq, 0*logq)` construction as the notebook's own cell, same
batch size) measured **0.9882** here, vs. **0.9730** printed in the
notebook itself -- a real, reproducible gap (not sampling noise at this
batch size). The blob is confirmed to be from that same 50,000-epoch run,
so a training-snapshot mismatch is ruled out; the cause isn't identified
(possibly a different Z batch than whatever was in scope in that notebook
cell at measurement time). Reported here rather than silently picked one,
since the load itself checks out exactly (zero missing/unexpected keys)
and the round-trip error is tiny either way.

Being trained, this sampler is *not* exact, so `log_importance_weight` is
not identically 0 the way SU(2)'s is -- but it *is* exactly computable:
the spectral-twist encode/decode Jacobian (`_spectral_twist.py`) is proven
exact for N = 3, not just N = 2, so the target's density is known even
though a tractable *sampler* for it isn't (that gap is exactly why this
file exists). See `sample_su3_group_commutator_xy_given_z`'s own docstring
for the formula.

Inputs must be `torch.complex128` (`torch.float64` real/imag) -- the
weights were trained in that precision and are not cast.
"""

# pylint: disable=invalid-name

import base64
import io

import torch

from lattice_ml.lie_groups import (
    decode_sun_group_commutator,
    compute_sun_group_commutator_log_prob,
)
from lattice_ml.lie_groups._sun_group_commutator import eig_with_options


from ._unitary_group import rand_sun_group_like, rand_diagonal_sun_group_like


__all__ = ["sample_su3_group_commutator_xy_given_z"]


_N_C = 3
_NUM_SPLINE_SEGMENTS = 8
_HIDDEN_SIZES = (32, 32, 32)
_STATE_DICT_PREFIX = "layers.1."
_MODEL_CACHE = None


# =============================================================================
def sample_su3_group_commutator_xy_given_z(Z: torch.Tensor):
    r"""
    Trained (not exact) sampler for X, Y in SU(3) given Z, `Z = X Y X† Y†`.

    See the module docstring for the lazy `normflow` import, why only the
    Q-conditional-flow (not the whole model) is loaded, the weights'
    provenance, and why this is not an exact sampler.

    Parameters
    ----------
    Z : torch.Tensor
        Special unitary input matrix of shape `(..., 3, 3)`, dtype
        `torch.complex128`.

    Returns
    -------
    X, Y : torch.Tensor
        One random pair of special unitary matrices satisfying
        `Z = X Y X† Y†`, drawn from the trained flow's approximation to
        the conditional law given Z.
    log_importance_weight : torch.Tensor
        `log p(X,Y|Z) − log q(X,Y|Z)`. Computable exactly even though the
        flow itself is not exact: `log p(X,Y|Z) = logj_decode − log J(Z)`
        uses the spectral-twist encode/decode Jacobian, proven exact for
        N = 3 (not just N = 2); `log q(X,Y|Z) = -logj`, the flow's own
        transform Jacobian, by the same change-of-variables argument as
        `sample_su2_group_commutator_xy_given_z`'s `log_db_ds`. What is
        *not* known for SU(3) is a tractable sampling map, not the target
        density -- this is exactly `-logq` in
        `su3_group_commutator.ipynb`'s own convention (`logq = logr_Z -
        logj_total`), so `exp(log_importance_weight)` reproduces the
        0.9882/0.9730 self-ESS figures already measured for this model.
    """
    q_module = _build_model()

    D = rand_diagonal_sun_group_like(Z)
    Q = rand_sun_group_like(Z)
    with torch.no_grad():
        Q, logj = q_module.forward(Q, args=(Z,))

    (X, Y), logj_decode = decode_sun_group_commutator(
        D, Q, Z, return_logj=True
    )

    log_importance_weight = (
        logj_decode + logj - compute_sun_group_commutator_log_prob(Z)
    )
    return (X, Y), log_importance_weight


# =============================================================================
# pylint: disable=import-outside-toplevel
def _build_model():
    """Build (once) and cache the Q-conditional-flow, importing `normflow`
    lazily. Only `layers.1.*` of the exported state dict is used."""
    global _MODEL_CACHE  # pylint: disable=global-statement
    if _MODEL_CACHE is not None:
        return _MODEL_CACHE

    try:
        from normflow.nn import Module_, MatrixModule_
        from normflow.nn import make_rqs_masked_autoreg_context_module
        from normflow.lib.matrix_handles import SUnMatrixEulerParametrizer
    except ImportError as exc:
        raise ImportError(
            "sample_su3_group_commutator_xy_given_z needs `normflow` "
            "installed and importable: no exact SU(3) sampler is known "
            "yet (see the module docstring), so this wraps (part of) the "
            "trained flow from normflow's own SU3 example notebook, whose "
            "architecture lives in `normflow.nn`/`normflow.lib`."
        ) from exc

    class _PartialTransform_(Module_):
        """Apply the transform to x[..., indices], passing the rest through."""

        def __init__(self, transform_, indices):
            super().__init__()
            self.transform_ = transform_
            self.register_buffer("indices", indices)

        def forward(self, x, log0=0, args=None):
            y, logj = self.transform_(x[..., self.indices], args=args)
            x = x.clone()
            x[..., self.indices] = y
            return x, log0 + logj

        def reverse(self, x, log0=0, args=None):
            y, logj = self.transform_.reverse(x[..., self.indices], args=args)
            x = x.clone()
            x[..., self.indices] = y
            return x, log0 + logj

    class _GroupCommutatorQTransform_(Module_):
        """Update Q conditional on Z -- ports su3_group_commutator.ipynb's
        `GroupCommutatorQTransform_` (Q_module_) verbatim.
        """

        eig_options = {
            'sort_by': 'zero-sum-angle', 'randomize_vector_phase': True,
            'project_to_sun': True,
        }

        def __init__(self, matrix_transform_):
            super().__init__()
            self.matrix_transform_ = matrix_transform_

        def forward(self, Q, log0=0, *, args):
            Z = args[0]
            lam_z, Omega_z = eig_with_options(Z, **self.eig_options)
            context = torch.flatten(torch.view_as_real(lam_z), start_dim=-2)
            P = Omega_z.adjoint() @ Q
            P, logj = self.matrix_transform_.forward(P, args=context)
            Q = Omega_z @ P
            return Q, log0 + logj

        def reverse(self, Q, log0=0, *, args):
            Z = args[0]
            lam_z, Omega_z = eig_with_options(Z, **self.eig_options)
            context = torch.flatten(torch.view_as_real(lam_z), start_dim=-2)
            P = Omega_z.adjoint() @ Q
            P, logj = self.matrix_transform_.reverse(P, args=context)
            Q = Omega_z @ P
            return Q, log0 + logj

    active_indices = torch.tensor([2, 3, 4, 5])
    param_net_ = _PartialTransform_(
        make_rqs_masked_autoreg_context_module(
            data_features=len(active_indices), context_features=2 * _N_C,
            n_segments=_NUM_SPLINE_SEGMENTS, hidden_sizes=_HIDDEN_SIZES,
            iaf=True,
        ),
        active_indices,
    )
    matrix_handle = SUnMatrixEulerParametrizer()
    matrix_transform_ = MatrixModule_(param_net_, matrix_handle=matrix_handle)
    q_module = _GroupCommutatorQTransform_(matrix_transform_)

    # Full state dict has layers.1.* (Q_module_, used here) and layers.2.*
    # (Z_module_, not needed -- see module docstring); no layers.0.* since
    # D_module_ = None has no parameters.
    full_state_dict = torch.load(
        io.BytesIO(base64.b64decode(_SU3_WEIGHTS_BLOB.strip())),
        map_location=torch.device('cpu'), weights_only=True,
    )
    q_state_dict = {
        k[len(_STATE_DICT_PREFIX):]: v for k, v in full_state_dict.items()
        if k.startswith(_STATE_DICT_PREFIX)
    }
    q_module.load_state_dict(q_state_dict)
    q_module.eval()

    _MODEL_CACHE = q_module
    return q_module


# =============================================================================
# Weights exported from su3_group_commutator.ipynb's
# `model.network_fn_.get_weights_blob()` (see module docstring); only the
# layers.1.* (Q_module_) entries of this state dict are actually used.
_SU3_WEIGHTS_BLOB = (
    ''
)
